package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.sheet.DatedSetting;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingController {

    /**
     * The sheet's settings as the screen shows them, each dated one as in force on the sheet's today,
     * with every value recorded for those in dated; the clerk limit has two decimals, null when none,
     * and so has the floor; the terms are in days, and so are gradeTerms, by grade, for each grade with
     * its own; the late percent has two decimals; the policy date
     * is null when blank (the sheet's today), and so is the period numbering from (off); the cap has
     * two decimals, null when none; permissions has the roles set for each action of the permission
     * matrix, comma separated, for each action with any set (the rest keep the standing rule); the grace
     * days are a whole number of days, null when blank (off); the entry date is null when blank (off); the pot has two decimals, null when none;
     * the parent is the id of the sheet it names as its parent, null when none; the fiscal start month
     * is the month (1 to 12) a fiscal year starts in; the alert threshold has two decimals, null when off;
     * the escalate after is a whole number of days, null when blank (off); so is the review SLA (none).
     */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, List<RoleView> roles, Map<String, Integer> gradeTerms, String cap,
            Map<String, List<DatedView>> dated, Map<String, String> permissions, Integer graceDays,
            LocalDate entryDate, String pot, String parent, int fiscalStartMonth, String alertThreshold,
            Integer escalateAfter, Integer reviewSla, String proofKinds) {}

    /** A value recorded for a dated setting from a date on; null when none. */
    public record DatedView(LocalDate from, String value) {}

    /** The values recorded for each dated setting, by key, earliest from-date first. */
    public static Map<String, List<DatedView>> datedViews(List<DatedSetting> dated) {
        Map<String, List<DatedView>> byKey = new TreeMap<>();
        for (DatedSetting d : dated) {
            byKey.computeIfAbsent(d.getKey(), k -> new ArrayList<>()).add(new DatedView(d.getFrom(), d.getValue()));
        }
        return byKey;
    }

    /** A user name's role, as clerk or steward. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole r) {
            return new RoleView(r.getUserName(), r.getRole().label());
        }
    }

    /** A clerk limit with at most two decimals; blank or null: no limit; recorded from the from-date (yyyy-mm-dd), blank or null: the sheet's today. */
    public record ClerkLimitRequest(@Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String value,
            @Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String from) {

        LocalDate fromValue() {
            return from == null || from.isEmpty() ? null : LocalDate.parse(from);
        }

        BigDecimal limitValue() {
            return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
        }
    }
        }
    }

    /** A parent: the id of a sheet; blank or null: none. */
    public record ParentRequest(@Size(max = 100) @Pattern(regexp = "\\s*([A-Za-z0-9._-]+)?\\s*") String value) {

        String parentValue() {
            return value == null || value.isBlank() ? null : value.strip();
        }
    }

    /** Proof kinds: a comma separated list of receipt and photo; blank or null: none. */
    public record ProofKindsRequest(@Size(max = 100)
            @Pattern(regexp = "\\s*((receipt|photo)(\\s*,\\s*(receipt|photo))*)?\\s*") String value) {

        String kindsValue() {
            if (value == null || value.isBlank()) return null;
            return String.join(",", Arrays.stream(value.split(",")).map(String::strip).distinct().toList());
        }
    }

    /** Grace days: a whole number of days; blank or null: off. */
    public record GraceDaysRequest(@Pattern(regexp = "(\\d{1,4})?") String value) {

        Integer daysValue() {
            return value == null || value.isEmpty() ? null : Integer.valueOf(value);
        }
    }

    /** Escalate after: a whole number of days; blank or null: off. */
    public record EscalateAfterRequest(@Pattern(regexp = "(\\d{1,4})?") String value) {
            return from == null || from.isEmpty() ? null : LocalDate.parse(from);
        }

        LocalDate toValue() {
            return LocalDate.parse(to);
        }
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping("/settings")
    public SettingsView get(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new SettingsView(text(service.clerkLimit(sheetId)), text(service.floor(sheetId)),
                service.terms(sheetId), text(service.latePct(sheetId)), service.policyDate(sheetId),
                service.periodNumberingFrom(sheetId),
                service.roles(sheetId).stream().map(RoleView::of).toList(), service.gradeTerms(sheetId),
                text(service.cap(sheetId)), datedViews(service.dated(sheetId)), service.permissions(sheetId),
                service.graceDays(sheetId), service.entryDate(sheetId), text(service.pot(sheetId)),
                service.parent(sheetId), service.fiscalStartMonth(sheetId), text(service.alertThreshold(sheetId)),
                service.escalateAfter(sheetId), service.reviewSla(sheetId),
                String.join(",", service.proofKinds(sheetId)));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClerkLimitRequest request) {
        service.setClerkLimit(sheetId, user, request.limitValue(), request.fromValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/floor")
    public SettingsView setFloor(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
    }

    @PutMapping("/settings/alert-threshold")
    public SettingsView setAlertThreshold(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid AlertThresholdRequest request) {
        service.setAlertThreshold(sheetId, user, request.thresholdValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/proof-kinds")
    public SettingsView setProofKinds(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ProofKindsRequest request) {
        service.setProofKinds(sheetId, user, request.kindsValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/parent")
    public SettingsView setParent(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ParentRequest request) {
        service.setParent(sheetId, user, request.parentValue());
        return get(sheetId, user);
    }

    @PutMapping("/settings/grace/{grade}")
    public SettingsView setGradeGrace(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid GradeGraceRequest request) {
        service.setGradeGrace(sheetId, user, grade, request.daysValue(), request.fromValue());
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.DatedSetting;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetParent;
import net.officefloor.hq.app.sheet.SheetParentRefusedException;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A sheet's settings: the role each user name has (clerk unless given another) and the clerk
 * limit, the highest due a clerk can settle (none: no limit); and the floor, the least a claim's
 * live due can be; and the terms, the days after its date by which a claim is due (fixed when it is
 * added), set for the sheet and, overriding it, for any grade; and the late
 * percent, which an overdue claim's due gains of its figure for every full 30 days overdue. Those are
 * dated: each save records its value from a from-date (the sheet's today unless given), and a claim
 * takes the floor, late percent and terms in force on its date, the clerk limit and cap those in force
 * on the sheet's today (see {@link Sheet}). And the
 * policy date (none: the sheet's today), before which a claim's live figures round half up, else half to even;
 * and the period numbering from (none: off), from which a claim opened is numbered within its period;
 * and the cap (none: no cap), the most a person's due-total can be; and the proof threshold (none: none,
 * dated, taken on a claim's date; a grade's own, when set, overrides it for a claim whose person has that grade on its date), above which a claim's due needs a proof to be settled or approved;
 * and the entry date (none: off, not dated), the date a new claim given none takes rather than the sheet's today;
 * and the grace days (none: off, not dated), past which an open period closes when the sheet's today changes;
 * and the grace days of each grade (none: none, dated, taken on a claim's date for its person's grade then),
 * past its due-by plus which a claim is overdue and from which its late charge's 30-day boundaries count;
 * and the permission matrix (not dated): for each action, the roles that may take it, blank keeping
 * its standing rule; and the parent (none: none, not dated), the sheet whose rates, then its parent's,
 * up to three levels up, a grade with no rate in force on a date takes.
 */
@Service
public class SettingService {

    /** The grades a person can have, each of which can have its own terms. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    /** The actions of the permission matrix, each with its standing rule: the roles that may take it while none are set. */
    public static final Map<String, Set<Role>> STANDING_PERMISSIONS;
    static {
        Map<String, Set<Role>> standing = new LinkedHashMap<>();
        for (String action : List.of("open", "settle", "void", "close")) standing.put(action, EnumSet.of(Role.CLERK, Role.STEWARD));
        for (String action : List.of("reassign", "reopen")) standing.put(action, EnumSet.of(Role.STEWARD));
        STANDING_PERMISSIONS = Map.copyOf(standing);
    }

        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user.strip() + " key=alert-threshold value="
                + (threshold == null ? "" : threshold.toPlainString()));
        return threshold;
    }

    /** Change the proof kinds (null: none), comma separated; not dated. */
    @Transactional
    public String setProofKinds(String sheetId, String user, String kinds) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
